 func TestParseHookEvent_AllHookTypes(t *testing.T) {
 	t.Parallel()

 	testCases := []struct {
 		hookName      string
 		expectedType  agent.EventType
 		expectNil     bool
 		inputTemplate string
 	}{
 		{
 			hookName:      HookNameSessionStart,
